{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "Encainide absolute oral bioavailability was 32±7% in normal subjects, above the 20% threshold; other encainide studies report mean F of 30–42%, with higher values in cirrhosis.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Zolpidem absolute oral bioavailability was about 70% in healthy volunteers, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Solifenacin absolute oral bioavailability was 88.0% (95% CI 75.8–102.1) in healthy volunteers, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C41"],
      "claim": "Quinapril absolute oral bioavailability was 45.9±11.2% in healthy participants, above the 20% threshold despite containing ionizable groups.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Celecoxib oral bioavailability is reported as 20–40%, at or above the 20% threshold, supporting a high classification for this endpoint.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Suvorexant mean oral bioavailability was 82% in humans, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Praziquantel bioavailability was 27.2±5.4% in patients, above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All high-transfer experimental analogues (assay-transfer scores ≥0.9848) show oral bioavailability at or above 20%, mostly 27–88%, consistently supporting a high F≥20% prediction. The physicochemical prior suggesting low permeability is outweighed by this strong, transferable experimental evidence, though no direct measurement exists for the exact query molecule.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the exact query molecule.",
    "The query's acidic sulfonylurea/semicarbazide and high TPSA/low logD are not represented by a structurally identical analogue; permeability and efflux behavior are inferred.",
    "First-pass metabolism and transporter-mediated effects for the query are not directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

